"/* Simple design system */
:root {
    --primary-color: #0066ff; /* simple blue */
    --bg-color: #ffffff;
    --text-color: #212121;
    --font-primary: 'Roboto', sans-serif;
    --spacing: 1rem;
    --border-radius: 4px;
    --transition: 0.2s;
}

* {box-sizing:border-box; margin:0; padding:0;}
body {font-family: var(--font-primary); background: var(--bg-color); color: var(--text-color); line-height:1.5;}
.container {max-width:1200px; margin:auto; padding: var(--spacing);}
header {background: var(--primary-color); color:#fff; padding: var(--spacing);}
nav {display:flex; justify-content:space-between; align-items:center;}
nav a {color:#fff; text-decoration:none; margin:0 var(--spacing);}
nav a:hover {opacity:0.8;}
.btn {display:inline-block; background:var(--primary-color); color:#fff; padding:0.5rem 1rem; border:none; border-radius:var(--border-radius); cursor:pointer; text-decoration:none; transition:var(--transition);} 
.btn:hover {background:#0052cc;}
.grid {display:grid; grid-template-columns:repeat(auto-fit, minmax(200px,1fr)); gap:var(--spacing);}
.card {border:1px solid #ddd; border-radius:var(--border-radius); padding:var(--spacing); background:#fafafa;}
.card img {max-width:100%; height:auto; border-radius:var(--border-radius);}
.footer {background:#f2f2f2; text-align:center; padding:var(--spacing); margin-top:var(--spacing);}
@media(max-width:600px){nav{flex-direction:column;}}"

